  const found = [];
  const notFound = [];
  // Unique and sorted, so the output only depends on the set of codes, not on their order
  for (const code of [...new Set(codes)].sort()) {
    if (Object.hasOwn(vehicle.codes, code)) {
      found.push({ code, description: vehicle.codes[code].description });
    } else {
      notFound.push(code);
    }
  }

  const merged = found.reduce((acc, { code }) => {
    for (const { cause, probability } of vehicle.codes[code].causes) {
      const entry = acc.get(cause);
      if (!entry) {
        acc.set(cause, { id: cause, probability, codes: [code] });
      } else {
        entry.probability = Math.max(entry.probability, probability);
        entry.codes.push(code);
      }
    }
    return acc;
  }, new Map());

  const causes = [...merged.values()]
    .map(({ id, probability, codes: causeCodes }) => {
      if (!Object.hasOwn(vehicle.causes, id)) {
        throw new Error(
